def filter_primes_1(numbers):
    primes = []
    for n in numbers:
        if n < 2:
            continue
        is_p = True
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                is_p = False
                break
        if is_p:
            primes.append(n)
    return primes
